import React, { useRef } from "react"

/**
 * SegmentedControl — a controlled tablist of mutually exclusive options.
 *
 * Props:
 *   options    array of strings, or of { label, value }
 *   value      the selected value (controlled; falls back to the first option)
 *   onChange   optional (value) => void
 *   ariaLabel  accessible name for the tablist
 *
 * Keyboard: ArrowLeft / ArrowRight (and Up / Down) move the selection with wrapping,
 * Home / End jump to the ends. Only the active tab is in the tab order.
 */

function normaliseOptions(options) {
  if (!Array.isArray(options)) return []
  return options.filter(option => option !== null && option !== undefined).map(option => {
    if (typeof option === "object") {
      const value = option.value !== undefined ? option.value : option.label
      const label = option.label !== undefined ? option.label : value
      return { label: label, value: value }
    }
    return { label: String(option), value: option }
  })
}

function SegmentedControl({ options, value, onChange, ariaLabel = "View options" }) {
  const buttonRefs = useRef([])
  const items = normaliseOptions(options)

  if (items.length === 0) return null

  const found = items.findIndex(item => item.value === value)
  const activeIndex = found === -1 ? 0 : found

  function select(index, moveFocus) {
    const next = items[index]
    if (!next) return
    if (typeof onChange === "function") onChange(next.value)
    if (moveFocus) {
      const node = buttonRefs.current[index]
      if (node && typeof node.focus === "function") node.focus()
    }
  }

  function handleKeyDown(event) {
    const last = items.length - 1
    let nextIndex = -1

    if (event.key === "ArrowRight" || event.key === "ArrowDown") {
      nextIndex = activeIndex === last ? 0 : activeIndex + 1
    } else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
      nextIndex = activeIndex === 0 ? last : activeIndex - 1
    } else if (event.key === "Home") {
      nextIndex = 0
    } else if (event.key === "End") {
      nextIndex = last
    }

    if (nextIndex === -1) return
    event.preventDefault()
    select(nextIndex, true)
  }

  return (
    <div className="segmented" role="tablist" aria-label={ariaLabel}>
      {items.map((item, index) => {
        const isActive = index === activeIndex
        return (
          <button
            key={String(item.value)}
            type="button"
            role="tab"
            aria-selected={isActive}
            tabIndex={isActive ? 0 : -1}
            className={
              isActive
                ? "segmented__option segmented__option--active"
                : "segmented__option"
            }
            ref={node => {
              buttonRefs.current[index] = node
            }}
            onClick={() => select(index, false)}
            onKeyDown={handleKeyDown}
          >
            {item.label}
          </button>
        )
      })}
    </div>
  )
}

export default SegmentedControl
