import React from "react"

/**
 * A data-driven price sparkline.
 *
 * THE RULE: the line, the reference level and the colour all describe the SAME
 * window. Tone comes from the window's own `direction` — derived from open vs
 * close of the series being drawn — never from a first-vs-last comparison of
 * some other timeframe. The earlier version sampled a one-month series while the
 * table printed the session change, so eight of fourteen rows showed a rising
 * green line beside a red percentage. A trader who spots that once stops
 * believing the rest of the screen.
 *
 * Pass a getTrend() result as `trend` and everything is consistent by
 * construction. `values` + `direction` remain available for callers that have
 * already sliced their own series.
 *
 * Rendering notes:
 *  - Fixed viewBox with preserveAspectRatio="none", so every sparkline in a
 *    table has identical dimensions and identical horizontal resolution.
 *  - The y-domain always includes the baseline, so the reference line cannot
 *    fall outside the drawn area.
 *  - A flat series would divide by a zero range; that case pins the line to the
 *    vertical centre instead of collapsing onto an edge.
 *  - Pure SVG, no measurement, no refs — renders identically on server and client.
 */

const INSET = 2 // px of vertical breathing room so the stroke is never clipped

export default function Sparkline({
  trend,
  values,
  direction,
  baseline,
  width = 88,
  height = 28,
  showBaseline = true,
  showArea = false,
  className,
  title,
}) {
  const series = trend && Array.isArray(trend.values) ? trend.values : values
  if (!Array.isArray(series) || series.length < 2) return null

  const tone = (trend ? trend.direction : direction) || "flat"
  const base = trend && trend.baseline !== undefined ? trend.baseline : baseline

  // The domain spans the data AND the baseline, so the reference line is always
  // inside the box.
  let min = Infinity
  let max = -Infinity
  for (const v of series) {
    if (!Number.isFinite(v)) continue
    if (v < min) min = v
    if (v > max) max = v
  }
  if (!Number.isFinite(min) || !Number.isFinite(max)) return null
  if (Number.isFinite(base)) {
    if (base < min) min = base
    if (base > max) max = base
  }

  const range = max - min
  const usable = height - INSET * 2
  const y = value =>
    range === 0
      ? height / 2
      : INSET + (1 - (value - min) / range) * usable

  const stepX = width / (series.length - 1)
  const points = series
    .map((v, i) => `${(i * stepX).toFixed(2)},${y(v).toFixed(2)}`)
    .join(" ")

  const baselineY = Number.isFinite(base) ? y(base) : null

  return (
    <svg
      className={["sparkline", className].filter(Boolean).join(" ")}
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      preserveAspectRatio="none"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : "true"}
      focusable="false"
    >
      {showArea && (
        <polygon
          className={"sparkline__area sparkline__area--" + tone}
          points={`0,${height} ${points} ${width},${height}`}
        />
      )}

      {showBaseline && baselineY !== null && (
        <line
          className="sparkline__baseline"
          x1="0"
          x2={width}
          y1={baselineY.toFixed(2)}
          y2={baselineY.toFixed(2)}
          vectorEffect="non-scaling-stroke"
        />
      )}

      <polyline
        className={"sparkline__line sparkline__line--" + tone}
        points={points}
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  )
}
